using SkiaSharp;
namespace KeyboardScreen.Core;
public sealed class FontFolderCatalog:IDisposable{private static readonly HashSet<string> Extensions=new(StringComparer.OrdinalIgnoreCase){".ttf",".otf"};private readonly FileSystemWatcher _watcher;private readonly Timer _timer;public string FolderPath{get;}public event EventHandler? FontsChanged;public FontFolderCatalog(string path){FolderPath=Path.GetFullPath(path);Directory.CreateDirectory(FolderPath);_timer=new Timer(_=>FontsChanged?.Invoke(this,EventArgs.Empty));_watcher=new FileSystemWatcher(FolderPath){EnableRaisingEvents=true};_watcher.Created+=Changed;_watcher.Changed+=Changed;_watcher.Deleted+=Changed;_watcher.Renamed+=Changed;}public IReadOnlyList<ScreenFontOption> Scan(){var result=new List<ScreenFontOption>{ScreenFontOption.Default};var builtinFile=ScreenFontOption.Default.FileName;foreach(var path in Directory.EnumerateFiles(FolderPath).Where(p=>Extensions.Contains(Path.GetExtension(p))).OrderBy(Path.GetFileName)){var file=Path.GetFileName(path);if(builtinFile is{}bf&&string.Equals(file,bf,StringComparison.OrdinalIgnoreCase))continue;try{using var face=SKTypeface.FromFile(path);if(face is null)continue;var family=string.IsNullOrWhiteSpace(face.FamilyName)?Path.GetFileNameWithoutExtension(path):face.FamilyName;result.Add(new ScreenFontOption("file:"+file.ToLowerInvariant(),family,family,file,new FontFamily(family,path)));}catch{}}return result;}private void Changed(object s,FileSystemEventArgs e){if(Extensions.Contains(Path.GetExtension(e.FullPath)))_timer.Change(350,Timeout.Infinite);}public void Dispose(){_watcher.Dispose();_timer.Dispose();}}
